const txt = String($input.first().json.data ?? '');
const rows = txt.split(/\r?\n/).filter(Boolean);
const head = rows[0].split(',');
const data = rows.slice(1).map(l => {
  const c = l.split(',');
  const o = {};
  head.forEach((h, i) => o[h] = c[i]);
  return o;
}).sort((a, b) => Number(b.n) - Number(a.n)).slice(0, 10);
if (!data.length) { throw new Error('CSV vacio'); }
return [{ json: { products: data } }];

const raw = $input.first().json.choices?.[0]?.message?.content;
if (!raw) { throw new Error('Respuesta vacia del modelo'); }
const parsed = JSON.parse(raw);
return [{ json: { acciones: parsed.acciones ?? [], generado: new Date().toISOString() } }];
